+      place-items: center;
+      border: 1px solid rgba(148, 163, 184, 0.24);
+      border-radius: 999px;
+      color: #d8ccff;
+      background: rgba(255, 255, 255, 0.04);
+      transition: transform 220ms ease, border-color 220ms ease, background 220ms ease;
+    }
+
