      const item = document.createElement("div");
      item.className = "example";

      const button = document.createElement("button");
      button.className = "question";
      button.type = "button";
      button.setAttribute("aria-expanded", "false");
      button.setAttribute("aria-controls", `answer-${index}`);
      button.innerHTML = `<span>${question}</span><span class="icon" aria-hidden="true">+</span>`;

      const answerWrap = document.createElement("div");
      answerWrap.className = "answer";
      answerWrap.id = `answer-${index}`;

      const answerInner = document.createElement("div");
      answerInner.className = "answer-inner";

      const paragraph = document.createElement("p");
      paragraph.textContent = answer;

      answerInner.append(paragraph);
      answerWrap.append(answerInner);
      item.append(button, answerWrap);

      button.addEventListener("click", () => {
        const isOpen = item.classList.toggle("is-open");
        button.setAttribute("aria-expanded", String(isOpen));
      });

      return item;
    }

    function FAQPage() {
      const app = document.createElement("div");
      app.className = "app";

      const hero = document.createElement("section");
      hero.className = "hero";
      hero.innerHTML = `
        <p class="eyebrow">Cat care FAQ</p>
        <h1>Curious about cats?</h1>
        <p class="subtitle">Quick answers to common questions about feline behavior, wellness, and daily care. Tap a question to reveal the answer.</p>
      `;

