      transition: grid-template-rows 240ms ease;
    }

    .example.is-open .answer {
      grid-template-rows: 1fr;
    }

    .answer-inner {
      overflow: hidden;
    }

    .answer p {
      margin: 0;
      padding: 0 26px 26px;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.75;
    }

    .footer-note {
      margin: 22px 0 0;
      color: #7f8aa3;
      font-size: 0.92rem;
      text-align: center;
    }

    @media (max-width: 640px) {
      .app {
        width: min(100% - 20px, 960px);
        padding: 42px 0;
      }

      .details {
        border-radius: 22px;
      }

      .question {
        padding: 20px;
      }

      .answer p {
        padding: 0 20px 22px;
      }
    }
  </style>
</head>
<body>
  <main id="root"></main>

  <script>
    const faqs = [
      {
        question: "Why do cats purr?",
        answer: "Cats often purr when they are content, but purring can also be a self-soothing behavior when they are stressed, healing, or asking for attention. Context and body language help reveal what your cat means."
      },
      {
        question: "How much sleep does a cat need?",
        answer: "Most adult cats sleep 12 to 16 hours a day, while kittens and senior cats may sleep even more. Cats are crepuscular, so they are naturally most active around dawn and dusk."
      },
      {
        question: "Why does my cat knead blankets or my lap?",
        answer: "Kneading is a comforting behavior cats learn as kittens while nursing. Adult cats often knead soft surfaces when they feel safe, relaxed, and attached to their person or resting spot."
      },
      {
        question: "Do indoor cats need enrichment?",
        answer: "Yes. Indoor cats benefit from climbing spaces, scratching posts, window views, puzzle feeders, play sessions, and cozy hiding places. Enrichment supports healthy exercise and reduces boredom."
      },
      {
        question: "How often should I trim my cat's claws?",
        answer: "Many cats need a light claw trim every two to four weeks, depending on activity level and scratching habits. Use cat-safe clippers and trim only the clear tip, avoiding the pink quick."
      },
      {
        question: "Why does my cat slow blink at me?",
        answer: "A slow blink is usually a relaxed, friendly signal. Cats often use it to show trust, and you can gently slow blink back to return the message."
      }
    ];

    function FAQItem({ question, answer, index }) {
      const item = document.createElement("div");
      item.className = "example";

      const button = document.createElement("button");
      button.className = "question";
      button.type = "button";
      button.setAttribute("aria-expanded", "false");
      button.setAttribute("aria-controls", `answer-${index}`);
      button.innerHTML = `<span>${question}</span><span class="icon" aria-hidden="true">+</span>`;

      const answerWrap = document.createElement("div");
      answerWrap.className = "answer";
      answerWrap.id = `answer-${index}`;

      const answerInner = document.createElement("div");
      answerInner.className = "answer-inner";

      const paragraph = document.createElement("p");
      paragraph.textContent = answer;

      answerInner.append(paragraph);
      answerWrap.append(answerInner);
      item.append(button, answerWrap);

      button.addEventListener("click", () => {
        const isOpen = item.classList.toggle("is-open");
        button.setAttribute("aria-expanded", String(isOpen));
      });

      return item;
    }

    function FAQPage() {
      const app = document.createElement("div");
      app.className = "app";

      const hero = document.createElement("section");
      hero.className = "hero";
      hero.innerHTML = `
        <p class="eyebrow">Cat care FAQ</p>
        <h1>Curious about cats?</h1>
        <p class="subtitle">Quick answers to common questions about feline behavior, wellness, and daily care. Tap a question to reveal the answer.</p>
      `;

      const details = document.createElement("section");
      details.className = "details";
      details.setAttribute("aria-label", "Frequently asked questions about cats");
      faqs.forEach((faq, index) => details.append(FAQItem({ ...faq, index })));

      const note = document.createElement("p");
      note.className = "footer-note";
      note.textContent = "For health concerns or sudden behavior changes, contact a veterinarian.";

      app.append(hero, details, note);
      return app;
    }

    document.getElementById("root").append(FAQPage());
  </script>
</body>
</html>
